<tr data-laporan-id="{{ $l->id }}" data-search="{{ strtolower(($l->satuan->nama ?? '').' '.$l->perihal) }}" data-prioritas="{{ $l->prioritas }}"><td>{{ $l->satuan->nama ?? '-' }}</td><td>{{ $l->perihal }}</td><td>{{ $l->prioritas }}</td><td><span class="status-dot {{ $l->status === \App\Models\Laporan::STATUS_PROGRES ? 'blue' : (str_contains(strtolower($l->status),'setuj') || str_contains(strtolower($l->status),'diterima') ? 'green' : (str_contains(strtolower($l->status),'tolak') ? 'bad' : 'amber')) }}">{{ $l->status === \App\Models\Laporan::STATUS_PROGRES ? 'Progres · '.$l->progres.'%' : $l->status }}</span></td><td>{{ $l->created_at->translatedFormat('d M Y H:i') }}</td><td><button type="button" class="monitor-detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($l->satuan->nama ?? '-') }}" data-tujuan="{{ e($l->tujuanSatuan->nama ?? '-') }}" data-perihal="{{ e($l->perihal) }}" data-prioritas="{{ e($l->prioritas) }}" data-progres="{{ $l->progres }}" data-kendala="{{ e($l->kendala ?? '') }}" data-proyek="{{ e($l->proyek ?? '-') }}" data-tanggal="{{ e($l->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($l->deskripsi) }}" data-lampiran="{{ $l->lampiran_path ? e(asset('storage/'.$l->lampiran_path)) : '' }}" data-readonly="1" data-readonly-text="Mode pemantauan Duktek — detail ini hanya untuk melihat aktivitas laporan.">Lihat Detail</button></td></tr>
